# Bank zadań autorskich — chemia, część 1: stechiometria, roztwory, roztwory wodne.
# B(tytuł, materiał, *zadania); T(typ, punkty, polecenie, odpowiedź, omówienie)
# Każde omówienie obliczeń: MODEL (dane → zależność) → RACHUNEK → SPRAWDZENIE (jednostka, zaokrąglenie, sens).
BANK = {'stechiometria': [
 B('Spalanie magnezu',
   'Tekst autorski. Wstążkę magnezu o masie 0,48 g spalono w powietrzu. Otrzymano białą substancję — tlenek magnezu. Przyjmij masy molowe: Mg — 24 g/mol, O — 16 g/mol.',
   T('podaj', 1, 'Napisz równanie reakcji spalania magnezu.', '2Mg + O₂ → 2MgO', 'Współczynniki: 2 atomy Mg i 2 atomy O po obu stronach.'),
   T('oblicz', 2, 'Oblicz masę tlenku magnezu, który powstał, jeśli magnez przereagował całkowicie. Wynik podaj w gramach z dokładnością do dwóch miejsc po przecinku.', 'm(MgO) = 0,80 g', 'MODEL: n(Mg) = m/M, z równania n(MgO) = n(Mg), m = n · M(MgO). RACHUNEK: n(Mg) = 0,48/24 = 0,02 mol; M(MgO) = 40 g/mol; m = 0,02 · 40 = 0,80 g. SPRAWDZENIE: masa produktu większa od masy Mg — zgodne z tym, że przyłączył się tlen.'),
   T('oblicz', 1, 'Oblicz objętość tlenu (w warunkach normalnych) potrzebną do spalenia tej porcji magnezu. Wynik podaj w cm³.', 'V(O₂) = 224 cm³', 'n(O₂) = n(Mg)/2 = 0,01 mol; V = 0,01 · 22,4 dm³ = 0,224 dm³ = 224 cm³. Pułapka: stosunek Mg : O₂ = 2 : 1, a nie 1 : 1.')),
 B('Wapień i kwas solny',
   'Tekst autorski. Próbkę wapienia o masie 12,5 g, zawierającą węglan wapnia i zanieczyszczenia niereagujące z kwasem, roztworzono w nadmiarze kwasu solnego. Wydzieliło się 2,24 dm³ CO₂ (warunki normalne). M(CaCO₃) = 100 g/mol.',
   T('podaj', 1, 'Napisz w formie jonowej skróconej równanie reakcji węglanu wapnia z kwasem solnym.', 'CaCO₃ + 2H⁺ → Ca²⁺ + CO₂↑ + H₂O', 'CaCO₃ jest trudno rozpuszczalny — zapisujemy go cząsteczkowo; Cl⁻ to jony widzowie.'),
   T('oblicz', 2, 'Oblicz zawartość procentową CaCO₃ w próbce wapienia.', '80%', 'MODEL: n(CO₂) → n(CaCO₃) (1 : 1) → m(CaCO₃) → % w próbce. RACHUNEK: n(CO₂) = 2,24/22,4 = 0,1 mol; m(CaCO₃) = 0,1 · 100 = 10 g; 10/12,5 · 100% = 80%. SPRAWDZENIE: wynik < 100% — próbka była zanieczyszczona, zgodnie z treścią.'),
   T('wyjasnij', 1, 'Wyjaśnij, dlaczego do obliczeń nie można użyć masy całej próbki wapienia.', 'Bo próbka zawiera zanieczyszczenia, które nie reagują z kwasem i nie dają CO₂; z kwasem reaguje tylko CaCO₃.', 'Typowy błąd CKE: niewłaściwa interpretacja składu mieszaniny.')),
 B('Synteza z wydajnością',
   'Tekst autorski. Amoniak otrzymuje się w reakcji N₂ + 3H₂ ⇄ 2NH₃. W reaktorze użyto 28 kg azotu i 9 kg wodoru. Otrzymano 13,6 kg amoniaku. M(N₂) = 28 g/mol, M(H₂) = 2 g/mol, M(NH₃) = 17 g/mol.',
   T('oblicz', 1, 'Ustal, który substrat został użyty w nadmiarze. Odpowiedź uzasadnij obliczeniami.', 'Wodór (H₂) jest w nadmiarze.', 'n(N₂) = 28 000/28 = 1000 mol; n(H₂) = 9000/2 = 4500 mol. Do 1000 mol N₂ potrzeba 3000 mol H₂, a jest 4500 mol — wodór jest w nadmiarze, a azot ogranicza ilość produktu.'),
   T('oblicz', 2, 'Oblicz wydajność reakcji.', 'W = 40%', 'MODEL: ilość teoretyczna z substratu w niedomiarze (N₂). RACHUNEK: 1000 mol N₂ → 2000 mol NH₃ → 2000 · 17 = 34 000 g = 34 kg; W = 13,6/34 · 100% = 40%. SPRAWDZENIE: W ≤ 100%.')),
], 'roztwory': [
 B('Roztwór do sterylizacji',
   'Tekst autorski. Należy przygotować 250 g 5-procentowego roztworu nadmanganianu potasu (manganianu(VII) potasu), a następnie rozcieńczyć go wodą do stężenia 0,1%.',
   T('oblicz', 1, 'Oblicz masy KMnO₄ i wody potrzebne do przygotowania roztworu 5%.', 'm(KMnO₄) = 12,5 g; m(H₂O) = 237,5 g', 'ms = Cp · mr / 100% = 5 · 250/100 = 12,5 g; woda = 250 − 12,5 = 237,5 g.'),
   T('oblicz', 2, 'Oblicz masę wody, którą trzeba dodać do całego roztworu 5%, aby otrzymać roztwór 0,1%.', '12 250 g wody (12,25 kg)', 'MODEL: masa substancji się nie zmienia; mr₂ = ms/Cp₂. RACHUNEK: mr₂ = 12,5/0,001 = 12 500 g; dodana woda = 12 500 − 250 = 12 250 g. SPRAWDZENIE: stężenie spada 50 razy, więc masa roztworu rośnie 50 razy (250 g · 50 = 12 500 g).')),
 B('Przeliczanie stężeń',
   'Tekst autorski. Stężony kwas solny ma stężenie 36% i gęstość 1,18 g/cm³. M(HCl) = 36,5 g/mol.',
   T('oblicz', 2, 'Oblicz stężenie molowe tego kwasu. Wynik podaj z dokładnością do jednego miejsca po przecinku.', 'Cm ≈ 11,6 mol/dm³', 'MODEL: Cm = Cp · d / (M · 100%), d w g/dm³. RACHUNEK: d = 1180 g/dm³; Cm = 36 · 1180 / (36,5 · 100) = 11,64 ≈ 11,6 mol/dm³. SPRAWDZENIE: typowy błąd to d = 1,18 g/cm³ bez przeliczenia — wynik 1000 razy za mały.'),
   T('oblicz', 1, 'Oblicz, jaką objętość tego kwasu trzeba odmierzyć, aby przygotować 500 cm³ roztworu HCl o stężeniu 0,5 mol/dm³.', 'ok. 21,5 cm³', 'n = 0,5 · 0,5 = 0,25 mol; V = n/Cm = 0,25/11,64 = 0,0215 dm³ ≈ 21,5 cm³.')),
 B('Krzywa rozpuszczalności',
   'Tekst autorski. Rozpuszczalność azotanu(V) potasu wynosi: w 20°C — 32 g/100 g wody, w 60°C — 110 g/100 g wody.',
   T('oblicz', 1, 'Oblicz stężenie procentowe nasyconego roztworu KNO₃ w 60°C.', 'ok. 52,4%', 'Cp = 110/(100 + 110) · 100% = 52,38%. Pułapka: dzielimy przez masę ROZTWORU (210 g), a nie wody.'),
   T('oblicz', 2, 'Nasycony w 60°C roztwór zawierający 100 g wody ochłodzono do 20°C. Oblicz masę wydzielonych kryształów.', '78 g', 'W 100 g wody w 60°C jest 110 g soli, w 20°C może być 32 g; wydzieli się 110 − 32 = 78 g.')),
], 'roztwory-wodne': [
 B('pH roztworów',
   'Tekst autorski. Przygotowano roztwory o stężeniu 0,01 mol/dm³: A — HCl, B — NaOH, C — CH₃COOH (Ka = 1,8 · 10⁻⁵), D — CH₃COONa.',
   T('podaj', 1, 'Uszereguj roztwory według rosnącego pH.', 'A < C < D < B', 'Mocny kwas (pH 2) < słaby kwas (pH ok. 3,4) < sól słabego kwasu i mocnej zasady (lekko zasadowy) < mocna zasada (pH 12).'),
   T('oblicz', 2, 'Oblicz pH roztworu C. Wynik podaj z dokładnością do jednego miejsca po przecinku.', 'pH ≈ 3,4', 'MODEL: słaby kwas, C₀/Ka = 0,01/1,8·10⁻⁵ ≈ 556 > 400, więc [H⁺] ≈ √(Ka·C₀). RACHUNEK: √(1,8·10⁻⁷) = 4,24·10⁻⁴; pH = −log(4,24·10⁻⁴) = 3,37 ≈ 3,4. SPRAWDZENIE: pH większe niż dla mocnego kwasu o tym samym stężeniu (2) — ma sens.'),
   T('podaj', 1, 'Napisz w formie jonowej skróconej równanie reakcji, która decyduje o odczynie roztworu D.', 'CH₃COO⁻ + H₂O ⇄ CH₃COOH + OH⁻', 'Hydrolizie ulega anion słabego kwasu; Na⁺ nie hydrolizuje.')),
 B('Zobojętnianie',
   'Tekst autorski. Zmieszano 50 cm³ roztworu HCl o stężeniu 0,2 mol/dm³ z 50 cm³ roztworu NaOH o stężeniu 0,1 mol/dm³. Przyjmij, że objętości się sumują.',
   T('oblicz', 2, 'Oblicz pH otrzymanego roztworu.', 'pH ≈ 1,3', 'MODEL: H⁺ + OH⁻ → H₂O, nadmiar H⁺ w łącznej objętości. RACHUNEK: n(H⁺) = 0,01 mol, n(OH⁻) = 0,005 mol; nadmiar 0,005 mol w 0,1 dm³ → [H⁺] = 0,05 mol/dm³; pH = −log 0,05 = 1,30. SPRAWDZENIE: roztwór kwasowy, bo kwasu było więcej.'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, jaką barwę przyjmie w tym roztworze fenoloftaleina. Uzasadnij.', 'Pozostanie bezbarwna, bo roztwór ma odczyn kwasowy (nadmiar jonów H⁺).', 'Fenoloftaleina barwi się na malinowo dopiero w środowisku zasadowym.')),
 B('Bufor octanowy',
   'Tekst autorski. Roztwór zawiera kwas octowy i octan sodu, oba o stężeniu 0,1 mol/dm³. pKa kwasu octowego = 4,74.',
   T('podaj', 1, 'Podaj pH tego roztworu.', 'pH = 4,74', 'Dla równych stężeń kwasu i soli pH = pKa (Henderson–Hasselbalch: log 1 = 0).'),
   T('podaj', 2, 'Napisz w formie jonowej skróconej równania reakcji zachodzących po dodaniu do buforu niewielkiej ilości: a) HCl, b) NaOH.', 'a) CH₃COO⁻ + H⁺ → CH₃COOH; b) CH₃COOH + OH⁻ → CH₃COO⁻ + H₂O', 'Jeden składnik buforu wiąże dodany kwas, drugi — zasadę; dlatego pH zmienia się nieznacznie.')),
]}
